<?php

declare(strict_types=1);namespace ProjectPress\Tests\Unit;use PHPUnit\Framework\TestCase;use ProjectPress\API\QualityRoutes;use ProjectPress\Includes\Core\Schema;use ProjectPress\Includes\Core\WP\Database;use ProjectPress\Includes\Project\Quality\Bug;use ProjectPress\Includes\Project\Quality\TestCase as QualityTestCase;final class PhaseNineQualityTest extends TestCase{public function testQualityTablesAreRegistered():void{Schema::register_tables();$tables=Database::get_core_tables();$this->assertArrayHasKey('bugs',$tables);$this->assertArrayHasKey('test_cases',$tables);}public function testQualityModelsRemainProjectScoped():void{$this->assertSame(12,(new Bug(array('project_id'=>12)))->get_project_id());$this->assertSame(12,(new QualityTestCase(array('project_id'=>12)))->get_project_id());}public function testQualityRestHandlersExist():void{foreach(array('index','create','update','delete','can_read','can_edit')as$method)$this->assertTrue(method_exists(QualityRoutes::class,$method));}public function testDeletionOwnsQualityTables():void{$source=file_get_contents(dirname(__DIR__,2).'/src/Includes/Project/Core/ProjectRepository.php');$this->assertStringContainsString("'bugs'",$source);$this->assertStringContainsString("'test_cases'",$source);}}
